// Uji end-to-end UI (Playwright/Chromium) terhadap: kode frontend NYATA + Netlify Functions NYATA + layanan inferensi Python NYATA (model joblib),
// dengan Supabase PALSU dan penyedia AI PALSU (lihat tests/support/fake-supabase.mjs). CDN (Chart.js/SweetAlert2/Lucide) DIBLOKIR sehingga jalur fallback yang teruji.
// Hasil ditulis ke tests/e2e/results.json -> dipakai untuk docs/TEST_REPORT.md.
import { createRequire } from 'node:module';
import { writeFileSync, mkdirSync } from 'node:fs';
import { startEnv, call, login as tokenOfRaw, PW, CSV } from '../support/harness.mjs';
import { _resetLimits } from '../../netlify/functions/_lib/core.js';
import { createServer } from '../../scripts/dev-server.mjs';
const require = createRequire('/usr/local/lib/node_modules/');
const { chromium } = require('playwright');

process.env.SETTINGS_CACHE_MS = '0'; // uji mengubah tabel langsung; cache pengaturan 5 dtk dimatikan agar perubahan terlihat
const env = await startEnv(); const srv = createServer(); await new Promise((r) => srv.listen(0, r));
const base = `http://127.0.0.1:${srv.address().port}`; const T = env.fake.state.tables; const browser = await chromium.launch();
const SHOTS = process.env.SHOTS_DIR; if (SHOTS) mkdirSync(SHOTS, { recursive: true });
const results = [];
// Pembatas laju login per-IP (30/5 menit) akan habis karena seluruh uji berasal dari satu IP lokal; direset sebelum tiap login uji. Uji pembatas sendiri (SEC-*) tidak memakai helper ini.
const tokenOf = (...a) => { _resetLimits(); return tokenOfRaw(...a); };
const ok = (c, m) => { if (!c) throw new Error(m || 'assertion gagal'); };
async function t(id, group, name, steps, expected, fn) {
  const t0 = Date.now();
  try { const actual = await fn(); results.push({ id, group, name, steps, expected, actual: actual || 'sesuai harapan', status: 'PASS', ms: Date.now() - t0 }); console.log('PASS', id, name); }
  catch (e) { results.push({ id, group, name, steps, expected, actual: String(e.message).split('\n')[0].slice(0, 300), status: 'FAIL', ms: Date.now() - t0 }); console.log('FAIL', id, name, '->', String(e.message).split('\n')[0]); if (process.env.DBG) console.log('   PAGE:', (await globalThis.__p?.locator('main').first().innerText().catch(() => '?'))?.slice(0, 400).replace(/\n/g, ' | ')); }
}
async function newPage(opts = {}) {
  const ctx = await browser.newContext({ viewport: opts.viewport || { width: 1280, height: 800 }, acceptDownloads: true }); await ctx.route(/cdn\.jsdelivr\.net/, (r) => r.abort());
  const p = await ctx.newPage(); p.errors = []; p.on('pageerror', (e) => p.errors.push(e.message)); p.setDefaultTimeout(9000); p.ctx = ctx; globalThis.__p = p; return p;
}
async function uiLogin(p, who, { pw = PW, remember = false, wait = true } = {}) {
  _resetLimits();
  await p.goto(base + '/login.html'); await p.fill('#f-email', who.includes('@') ? who : `${who}@test.id`); await p.fill('#f-password', pw); if (remember) await p.check('input[name=remember]'); await p.click('button[type=submit]');
  if (wait) await p.waitForURL(/\/(admin|user)\/dashboard\.html/);
}
const txt = (p, s = 'main') => p.locator(s).first().innerText();
const confirmDlg = async (p, label) => { await p.locator('.overlay .modal footer .btn', { hasText: label }).click(); };
const rice = { N: '90', P: '42', K: '43', temperature: '20.9', humidity: '82', ph: '6.5', rainfall: '203' };
async function fillExam(p, v) { for (const [k, val] of Object.entries(v)) await p.fill(`#f-${k}`, val); }
const shot = (p, n) => SHOTS && p.screenshot({ path: `${SHOTS}/${n}.png`, fullPage: false });

