for (const [name, vp] of [['smartphone-375', { width: 375, height: 740 }], ['tablet-768', { width: 768, height: 1024 }], ['desktop-1440', { width: 1440, height: 900 }]]) {
  const pages = { admin: ['/admin/dashboard.html', '/admin/users.html', '/admin/datasets.html', '/admin/examinations.html', '/admin/reports.html', '/admin/models.html', '/admin/audit-logs.html', '/admin/settings.html', '/ai-assistant/assistant.html'], budi: ['/user/dashboard.html', '/user/prediction.html', '/user/history.html', '/user/profile.html', '/ai-assistant/assistant.html'] };
  await t(`RESP-${name}`, 'Tampilan', `Tanpa overflow horizontal di ${name}`, `Buka 14 halaman pada viewport ${vp.width}x${vp.height}`, 'scrollWidth <= lebar viewport pada semua halaman; tanpa JS error', async () => {
    const bad = []; for (const [who, list] of Object.entries(pages)) { const p = await newPage({ viewport: vp }); await uiLogin(p, who === 'budi' ? 'budi' : who, { pw: PW }); for (const u of list) { await p.goto(base + u); await p.waitForTimeout(700); const w = await p.evaluate(() => [document.documentElement.scrollWidth, innerWidth]); if (w[0] > w[1] + 1) bad.push(`${u}:${w[0]}>${w[1]}`); if (p.errors.length) bad.push(`${u}: js error ${p.errors[0]}`); if (vp.width === 375 && SHOTS && /(dashboard|prediction|history)\.html/.test(u)) await shot(p, `${name}-${who}-${u.split('/').pop().replace('.html', '')}`); } await p.ctx.close(); }
    ok(!bad.length, bad.join(' | ')); return '14 halaman diperiksa'; });
}
